messages.content:
Game edukasi Endless Runner "Nusantara Heritage Run" siap dibangun dengan tiga kategori peninggalan (Candi Hindu, Candi Buddha, Masjid) dan tema Retro Pixel. Asumsi penting: rintangan berupa batu dan akar berukuran sedang agar tetap bisa dilompati pada tempo Normal.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "nusantara-heritage-run", title: "Nusantara Heritage Run", seed: "nusantara-01",
  theme: { preset: "retro-pixel" },

  learning: {
    subject: "Sejarah Indonesia",
    concept: "Peninggalan kerajaan Hindu-Buddha dan kerajaan Islam di Nusantara",
    objectives: ["Mengelompokkan peninggalan sejarah berdasarkan corak keagamaannya"],
    misconceptions: ["Candi Borobudur dianggap candi Hindu, padahal candi Buddha"],
    mode: "category",
    categories: [
      { id: "candi-hindu",   label: "Candi Hindu",   color: "#E5484D" },
      { id: "candi-buddha",  label: "Candi Buddha",  color: "#F2994A" },
      { id: "masjid",        label: "Masjid",        color: "#3FA34D" }
    ],
    items: [
      { id: "prambanan",   label: "Candi Prambanan",  category: "candi-hindu",  explain: "Candi Hindu terbesar di Indonesia, peninggalan Mataram Kuno." },
      { id: "gedong-songo", label: "Candi Gedong Songo", category: "candi-hindu", explain: "Kompleks candi Hindu di lereng Gunung Ungaran." },
      { id: "sukuh",       label: "Candi Sukuh",      category: "candi-hindu",  explain: "Candi Hindu bercorak unik di lereng Gunung Lawu." },
      { id: "borobudur",   label: "Candi Borobudur",  category: "candi-buddha", explain: "Candi Buddha terbesar di dunia, peninggalan Dinasti Syailendra." },
      { id: "mendut",      label: "Candi Mendut",     category: "candi-buddha", explain: "Candi Buddha di dekat Borobudur dengan arca Buddha besar." },
      { id: "sewu",        label: "Candi Sewu",       category: "candi-buddha", explain: "Kompleks candi Buddha di dekat Prambanan." },
      { id: "masjid-demak", label: "Masjid Demak",    category: "masjid",       explain: "Masjid tertua di Jawa, peninggalan Kesultanan Demak." },
      { id: "masjid-kudus", label: "Masjid Kudus",    category: "masjid",       explain: "Masjid dengan menara berbentuk candi, bukti akulturasi." },
      { id: "masjid-banten", label: "Masjid Banten",  category: "masjid",       explain: "Masjid peninggalan Kesultanan Banten." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "akar", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
